{
  "title": "Is the new checkout really winning?",
  "setting": "Day 3 at Breeze Goods",
  "mission": "Decide whether the new checkout flow actually boosts orders or if the early lead is just luck, and **deliver a clear recommendation** to the product team.",
  "deadline": "Review with {{product}} at 2:00 PM today",
  "panels": [
    {
      "title": "Checkout A/B Test (Day 2 of 14)",
      "metrics": [
        {
          "label": "Version A (Original)",
          "value": "5.0%",
          "note": "100 orders / 2,000 visitors"
        },
        {
          "label": "Version B (New design)",
          "value": "6.5%",
          "note": "130 orders / 2,000 visitors"
        },
        {
          "label": "Planned sample",
          "value": "8,000 / variant",
          "note": "25% collected so far"
        }
      ],
      "note": "Calculated baseline target: 8,000 visits per variant to reliably spot a 1% lift."
    }
  ],
  "team": [
    {
      "id": "product",
      "role": "Product manager",
      "expertise": "Wants to ship changes quickly to hit quarterly revenue goals",
      "ai": false
    },
    {
      "id": "data",
      "role": "Senior data analyst",
      "expertise": "Guards experimental rigor and guards against false positives",
      "ai": false
    },
    {
      "id": "ai",
      "role": "Stats Assistant",
      "expertise": "Runs sample size simulations and significance checks instantly",
      "ai": true
    }
  ],
  "meters": [
    {
      "id": "decision-risk",
      "label": "Risk of a wrong call",
      "start": 60,
      "goodWhen": "low"
    },
    {
      "id": "stakeholder-trust",
      "label": "{{product}}'s confidence",
      "start": 50,
      "goodWhen": "high"
    }
  ],
  "skills": [
    {
      "id": "real-difference",
      "name": "Tell a real difference from chance",
      "practice": "Look at an early coin-toss streak and write why 7 heads out of 10 does not prove a loaded coin."
    },
    {
      "id": "sample-size",
      "name": "Choose a sample size",
      "practice": "Calculate or explain why smaller improvements require much larger audiences to detect."
    },
    {
      "id": "explain-result",
      "name": "Explain a test result",
      "practice": "Summarize a statistical conclusion using everyday language without saying 'p-value'."
    }
  ],
  "startNodeId": "early-stop-pressure",
  "nodes": [
    {
      "id": "early-stop-pressure",
      "messages": [
        {
          "from": "product",
          "text": "Version B is crushing it! A 30% relative jump after just 48 hours. Let's switch 100% of traffic right now."
        },
        {
          "from": "data",
          "text": "Remember our experiment design. We only have a quarter of our planned visits."
        }
      ],
      "prompt": "How do you respond to {{product}}'s urge to roll out Version B immediately?",
      "choices": [
        {
          "id": "agree-and-ship",
          "text": "Agree with {{product}} and declare Version B the winner today.",
          "quality": "weak",
          "replies": [
            {
              "from": "data",
              "text": "Stopping early on a lucky streak is the easiest way to fool ourselves."
            }
          ],
          "effects": [
            {
              "meter": "decision-risk",
              "change": 30
            },
            {
              "meter": "stakeholder-trust",
              "change": 10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "real-difference",
              "kind": "improve",
              "text": "Early random spikes happen frequently in small samples and often vanish with more data.",
              "example": "\"Early swings are common when flipping a coin just a few times; we need more data to be sure.\""
            }
          ],
          "next": "post-mortem"
        },
        {
          "id": "ask-ai-significance",
          "text": "Ask {{ai}} to check if a 30-order difference at 2,000 visits could easily be random noise.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "With 2,000 visitors per group, there is still roughly a 5% to 8% chance of seeing this gap purely from natural fluctuation. We need 8,000 to be confident."
            },
            {
              "from": "product",
              "text": "Wait, really? Even with a 1.5 percentage point difference?"
            }
          ],
          "effects": [
            {
              "meter": "decision-risk",
              "change": -20
            },
            {
              "meter": "stakeholder-trust",
              "change": 5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "real-difference",
              "kind": "good",
              "text": "You verified whether the current lead exceeded typical random noise before celebrating.",
              "example": null
            }
          ],
          "next": "explain-sample-size"
        },
        {
          "id": "cite-p-value",
          "text": "Tell {{product}} that our alpha threshold isn't satisfied and the p-value is too fragile.",
          "quality": "fair",
          "replies": [
            {
              "from": "product",
              "text": "I don't know what alpha threshold means. I just see 130 sales versus 100 sales."
            },
            {
              "from": "data",
              "text": "Let's put that in plain business language so we can agree on next steps."
            }
          ],
          "effects": [
            {
              "meter": "decision-risk",
              "change": -10
            },
            {
              "meter": "stakeholder-trust",
              "change": -15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain-result",
              "kind": "improve",
              "text": "Technical jargon like 'alpha' and 'p-value' confuses non-analysts and weakens your argument.",
              "example": "\"Think of it like a sports game: a team leading after five minutes hasn't won the match yet.\""
            }
          ],
          "next": "explain-sample-size"
        }
      ]
    },
    {
      "id": "explain-sample-size",
      "messages": [
        {
          "from": "product",
          "text": "Why do we have to wait for 8,000 shoppers per version if B is already ahead? Every day we wait feels like lost revenue."
        }
      ],
      "prompt": "How do you explain why reaching the planned sample size matters?",
      "choices": [
        {
          "id": "explain-coin-analogy",
          "text": "Explain using a coin flip analogy: flipping 7 heads out of 10 is common, but 70 out of 100 shows real bias.",
          "quality": "strong",
          "replies": [
            {
              "from": "product",
              "text": "That makes total sense. Small samples get fluky streaks. Let's keep running it."
            }
          ],
          "effects": [
            {
              "meter": "decision-risk",
              "change": -20
            },
            {
              "meter": "stakeholder-trust",
              "change": 25
            }
          ],
          "timeJump": {
            "label": "10 days later",
            "panel": {
              "title": "Checkout A/B Test (Day 12 of 14)",
              "metrics": [
                {
                  "label": "Version A (Original)",
                  "value": "5.1%",
                  "note": "408 orders / 8,000 visitors"
                },
                {
                  "label": "Version B (New design)",
                  "value": "5.9%",
                  "note": "472 orders / 8,000 visitors"
                },
                {
                  "label": "Planned sample",
                  "value": "8,000 / variant",
                  "note": "100% collected"
                }
              ],
              "note": "Full sample reached. Version B shows a sustained +0.8 percentage point lift."
            }
          },
          "notes": [
            {
              "skill": "sample-size",
              "kind": "good",
              "text": "You explained sample size with a clear mental model that non-technical teammates grasp instantly.",
              "example": null
            }
          ],
          "next": "final-recommendation"
        },
        {
          "id": "compromise-traffic",
          "text": "Compromise by shifting to 70% Version B now and keeping 30% on Version A to finish faster.",
          "quality": "fair",
          "replies": [
            {
              "from": "data",
              "text": "Changing allocation mid-flight adds new confounding factors, though we can still salvage it with extra runtime."
            },
            {
              "from": "product",
              "text": "Okay, at least we capture some upside while gathering the remaining shoppers."
            }
          ],
          "effects": [
            {
              "meter": "decision-risk",
              "change": 10
            },
            {
              "meter": "stakeholder-trust",
              "change": 10
            }
          ],
          "timeJump": {
            "label": "10 days later",
            "panel": {
              "title": "Checkout A/B Test (Mid-flight adjustment)",
              "metrics": [
                {
                  "label": "Version A (Original)",
                  "value": "5.0%",
                  "note": "250 orders / 5,000 visitors"
                },
                {
                  "label": "Version B (New design)",
                  "value": "5.8%",
                  "note": "638 orders / 11,000 visitors"
                },
                {
                  "label": "Planned sample",
                  "value": "Uneven split",
                  "note": "Total sample reached"
                }
              ],
              "note": "Unequal sample sizes require adjusted calculations, but the signal appears steady."
            }
          },
          "notes": [
            {
              "skill": "sample-size",
              "kind": "improve",
              "text": "Altering split ratios mid-stream complicates the analysis and risks time-of-week distortion.",
              "example": "\"Sticking to equal 50/50 splits until the planned visitor count completes yields the cleanest read.\""
            }
          ],
          "next": "final-recommendation"
        },
        {
          "id": "rigid-rejection",
          "text": "Say we cannot launch because company policy requires two full weeks regardless of results.",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "Blindly following rules without understanding why frustrates the whole team."
            }
          ],
          "effects": [
            {
              "meter": "decision-risk",
              "change": -5
            },
            {
              "meter": "stakeholder-trust",
              "change": -20
            }
          ],
          "timeJump": {
            "label": "10 days later",
            "panel": {
              "title": "Checkout A/B Test (Day 12 of 14)",
              "metrics": [
                {
                  "label": "Version A (Original)",
                  "value": "5.1%",
                  "note": "408 orders / 8,000 visitors"
                },
                {
                  "label": "Version B (New design)",
                  "value": "5.9%",
                  "note": "472 orders / 8,000 visitors"
                },
                {
                  "label": "Planned sample",
                  "value": "8,000 / variant",
                  "note": "100% collected"
                }
              ],
              "note": "Target sample reached despite team tension."
            }
          },
          "notes": [
            {
              "skill": "explain-result",
              "kind": "improve",
              "text": "Invoking strict rules instead of explaining risk makes data practices feel like road blocks.",
              "example": "\"Waiting protects us from spending months building on what could be an illusion.\""
            }
          ],
          "next": "final-recommendation"
        }
      ]
    },
    {
      "id": "final-recommendation",
      "messages": [
        {
          "from": "product",
          "text": "Full sample is in. B settled from a 1.5 point jump down to about a 0.8 point jump (5.9% vs 5.1%). Is this real, and do we ship?"
        },
        {
          "from": "ai",
          "text": "With 8,000 visits per variant, the probability of this gap being random noise is under 1%."
        }
      ],
      "prompt": "How do you present the final decision to {{product}}?",
      "choices": [
        {
          "id": "recommend-rollout-clearly",
          "text": "Recommend rolling out Version B: the lead narrowed as expected, but the steady 0.8% gain is proven real.",
          "quality": "strong",
          "replies": [
            {
              "from": "product",
              "text": "Brilliant. That translates to roughly 80 extra sales per 10,000 visits. Let's roll it out to 100%."
            },
            {
              "from": "data",
              "text": "Spot-on analysis. Patiently testing prevented false hype and confirmed real value."
            }
          ],
          "effects": [
            {
              "meter": "decision-risk",
              "change": -20
            },
            {
              "meter": "stakeholder-trust",
              "change": 25
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain-result",
              "kind": "good",
              "text": "You connected statistical validity directly to business impact with zero confusing jargon.",
              "example": null
            }
          ],
          "next": "success-ending"
        },
        {
          "id": "keep-testing-forever",
          "text": "Suggest running for another month just to be 99.9% sure the difference isn't noise.",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "We hit our sample size and verified the effect. Waiting longer just delays real sales."
            }
          ],
          "effects": [
            {
              "meter": "decision-risk",
              "change": -5
            },
            {
              "meter": "stakeholder-trust",
              "change": -30
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "sample-size",
              "kind": "improve",
              "text": "Once your planned sample provides decisive evidence, extra runtime costs time and lost revenue.",
              "example": "\"Our plan accounted for this scenario; we have reached statistical confidence and can act.\""
            }
          ],
          "next": "hesitant-ending"
        }
      ]
    },
    {
      "id": "post-mortem",
      "messages": [
        {
          "from": "product",
          "text": "Wait... we switched everyone to B three weeks ago, but our overall conversion rate actually dipped back to 5.0%."
        },
        {
          "from": "data",
          "text": "That early 6.5% was random variation in a tiny window. We launched a change that gave zero real lift."
        }
      ],
      "prompt": "What lesson do you document in the test review?",
      "choices": [
        {
          "id": "document-peeking-trap",
          "text": "Document that stopping tests when early numbers look good leads to 'winner's curse' and false discoveries.",
          "quality": "strong",
          "replies": [
            {
              "from": "product",
              "text": "Ouch. Painful lesson, but now I see why we set sample targets beforehand."
            }
          ],
          "effects": [
            {
              "meter": "decision-risk",
              "change": -10
            },
            {
              "meter": "stakeholder-trust",
              "change": 15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "real-difference",
              "kind": "good",
              "text": "You correctly diagnosed why early stopping produces false positives.",
              "example": null
            }
          ],
          "next": "false-positive-ending"
        },
        {
          "id": "blame-seasonality",
          "text": "Suggest that consumer behavior shifted unpredictably and random bad luck hit Version B.",
          "quality": "weak",
          "replies": [
            {
              "from": "data",
              "text": "No, the math explains it completely. Small samples create artificial spikes."
            }
          ],
          "effects": [
            {
              "meter": "decision-risk",
              "change": 20
            },
            {
              "meter": "stakeholder-trust",
              "change": -15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "real-difference",
              "kind": "improve",
              "text": "Look at sample variance before looking for external excuses like seasonality.",
              "example": "\"The early difference was within expected random chance, so regression to the mean was inevitable.\""
            }
          ],
          "next": "false-positive-ending"
        }
      ]
    }
  ],
  "endings": [
    {
      "id": "success-ending",
      "outcome": "Version B rolled out with solid evidence: a real increase from 5.1% to 5.9% conversion, netting about 80 extra sales every 10,000 visitors without relying on lucky streaks."
    },
    {
      "id": "false-positive-ending",
      "outcome": "Rolling out early chased an illusion: the initial 6.5% peak melted away, leaving the company with the original 5.0% rate and engineering time spent maintaining an ineffective redesign."
    },
    {
      "id": "hesitant-ending",
      "outcome": "The team kept testing long after reaching conclusive proof, missing weeks of real revenue improvements and eroding product confidence in data-driven decisions."
    }
  ],
  "summary": [
    "Small early samples often create dramatic streaks that fade as more observations accumulate.",
    "A target sample size guarantees you collect enough evidence to separate genuine effects from random fluctuation.",
    "Explaining statistical significance through relatable concepts like coin tosses builds alignment much faster than technical terms."
  ]
}

{
  "title": "E se a luz viesse em gotas visíveis?",
  "setting": "Laboratório de imaginação",
  "mission": "Investigar **como o mundo funcionaria se pudéssemos enxergar a luz dividida em seus pacotes fundamentais**, os quanta.",
  "deadline": null,
  "panels": [
    {
      "title": "O feixe da lanterna comum",
      "metrics": [
        {
          "label": "Sensação humana",
          "value": "Contínua",
          "note": "Parece um fluxo liso e constante"
        },
        {
          "label": "Realidade quântica",
          "value": "Em pacotes",
          "note": "Formada por incontáveis 'grãos' de energia"
        }
      ],
      "note": "No cotidiano, os pacotes são tão minúsculos e velozes que tudo parece uma rampa contínua."
    }
  ],
  "team": [
    {
      "id": "curioso",
      "role": "Curioso da equipe",
      "expertise": "Faz perguntas do dia a dia para entender o mundo físico",
      "ai": false
    },
    {
      "id": "ia",
      "role": "Assistente de simulação",
      "expertise": "Cria analogias visuais simples para conceitos microscópicos",
      "ai": true
    }
  ],
  "meters": [
    {
      "id": "clareza",
      "label": "Clareza das ideias",
      "start": 50,
      "goodWhen": "high"
    }
  ],
  "skills": [
    {
      "id": "energia-em-pacotes",
      "name": "Energia em pacotes",
      "practice": "Explique a diferença entre uma rampa suave e uma escada de degraus para ilustrar a energia da luz."
    },
    {
      "id": "dualidade-onda-particula",
      "name": "Dualidade onda-partícula",
      "practice": "Dê um exemplo de como a luz pode bater como pedra mas ondular como marola na água."
    }
  ],
  "startNodeId": "dimmer-switch",
  "nodes": [
    {
      "id": "dimmer-switch",
      "messages": [
        {
          "from": "curioso",
          "text": "Se a luz vem em 'pacotes' chamados quanta, imagine que instalamos um botão giratório de volume na nossa lanterna para diminuir o brilho quase a zero."
        },
        {
          "from": "ia",
          "text": "Podemos desacelerar o tempo mentalmente. Se você girar esse botão até o menor nível imaginável, o que deveríamos ver saindo da lâmpada?"
        }
      ],
      "prompt": "Como a luz se comporta se você diminuir o brilho até o menor valor possível?",
      "choices": [
        {
          "id": "como-degraus",
          "text": "Ela para de diminuir de forma lisa e passa a pingar em unidades individuais, como gotas indivisíveis.",
          "quality": "strong",
          "replies": [
            {
              "from": "ia",
              "text": "Exatamente! Cada gota é um pacote de energia (um quantum). Você não consegue ter meia gota de luz saindo dali."
            }
          ],
          "effects": [
            {
              "meter": "clareza",
              "change": 25
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "energia-em-pacotes",
              "kind": "good",
              "text": "Você usou a ideia de degraus ou gotas para mostrar que a energia quântica não se divide infinitamente.",
              "example": null
            }
          ],
          "next": "dupla-fenda"
        },
        {
          "id": "fio-infinito",
          "text": "Ela vai enfraquecendo como um fio de água contínuo até sumir por completo, sem interrupções.",
          "quality": "weak",
          "replies": [
            {
              "from": "curioso",
              "text": "Parece o que vemos no dia a dia, mas a física quântica descobriu que existe um limite mínimo!"
            },
            {
              "from": "ia",
              "text": "A energia não é uma rampa lisa; ela é feita de pequenos degraus. Há um 'tijolo' mínimo que não dá para cortar."
            }
          ],
          "effects": [
            {
              "meter": "clareza",
              "change": -15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "energia-em-pacotes",
              "kind": "improve",
              "text": "Pensar na luz como um fluxo perfeitamente liso é a visão clássica. Na física quântica, a energia chega em blocos indivisíveis.",
              "example": "A energia não desliza numa rampa lisa; ela pula de degrau em degrau."
            }
          ],
          "next": "dupla-fenda"
        }
      ]
    },
    {
      "id": "dupla-fenda",
      "messages": [
        {
          "from": "curioso",
          "text": "Incrível, agora estamos vendo esses 'grãos' ou 'gotas' saindo um por um da lanterna! Mas e se colocarmos um papelão com duas frestas na frente deles?"
        },
        {
          "from": "ia",
          "text": "Se jogarmos bolinhas comuns por duas frestas, teríamos duas fileiras retas na parede. Mas com os pacotes de luz, na parede do fundo aparece um desenho de listras alternadas, claras e escuras."
        }
      ],
      "prompt": "Por que 'gotas' individuais de luz formam listras na parede como se fossem ondas no mar?",
      "choices": [
        {
          "id": "onda-e-particula",
          "text": "Porque a luz tem dupla personalidade: viaja se espalhando como onda, mas atinge a parede como partícula individual.",
          "quality": "strong",
          "replies": [
            {
              "from": "ia",
              "text": "Perfeito! Cada pacote interfere consigo mesmo pelo caminho como uma onda na água, mas marca presença na tela como um pontinho sólido."
            }
          ],
          "effects": [
            {
              "meter": "clareza",
              "change": 25
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "dualidade-onda-particula",
              "kind": "good",
              "text": "Você capturou a essência da dualidade: a luz viaja como onda ondulante e bate como partícula concentrada.",
              "example": null
            }
          ],
          "next": "fim-compreensao-alta"
        },
        {
          "id": "apenas-bolinhas",
          "text": "Porque as bolinhas de luz simplesmente ricocheteiam nas bordas das frestas e se acumulam por acaso.",
          "quality": "fair",
          "replies": [
            {
              "from": "curioso",
              "text": "Até parece ricochete, mas o desenho na parede é certinho demais para ser apenas batidas aleatórias."
            },
            {
              "from": "ia",
              "text": "Esse padrão de listras é a assinatura clássica de ondas que se somam e se cancelam, mesmo quando enviamos um pacote de cada vez!"
            }
          ],
          "effects": [
            {
              "meter": "clareza",
              "change": -5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "dualidade-onda-particula",
              "kind": "improve",
              "text": "Tratar o quantum apenas como uma pedrinha que rebate esquece o lado ondulatório que dita para onde ele viaja.",
              "example": "A luz age como pacote ao tocar a parede, mas no caminho ela se espalha como onda."
            }
          ],
          "next": "fim-compreensao-media"
        }
      ]
    }
  ],
  "endings": [
    {
      "id": "fim-compreensao-alta",
      "outcome": "Você desvendou o coração da física quântica: a luz não é uma rampa contínua, mas sim uma chuva de pacotes que viajam como ondas e tocam o mundo como partículas."
    },
    {
      "id": "fim-compreensao-media",
      "outcome": "Você viu que a luz é formada por pequenos blocos fundamentais, embora sua estranha dança entre ser onda e ser partícula ainda pareça mágica aos nossos olhos comuns."
    }
  ],
